import time

class SlidingWindow:
    def __init__(self, window_seconds: float):
        self.window = window_seconds
        self._entries: list[tuple[float, float]] = []

    def record(self, val: float, ts: float | None = None) -> None:
        now = ts if ts is not None else time.monotonic()
        self._entries.append((now, val))
        self._purge(now)

    def _purge(self, now: float) -> None:
        cutoff = now - self.window
        self._entries = [e for e in self._entries if e[0] >= cutoff]

    def mean(self, now: float | None = None) -> float:
        self._purge(now if now is not None else time.monotonic())
        if not self._entries: return 0.0
        return sum(e[1] for e in self._entries) / len(self._entries)

