import unittest
from metrics.window import SlidingWindow

class TestWindow(unittest.TestCase):
    def test_sliding(self):
        sw = SlidingWindow(10.0)
        sw.record(10.0, ts=1.0)
        sw.record(20.0, ts=5.0)
        self.assertEqual(sw.mean(ts := 6.0), 15.0)
        self.assertEqual(sw.mean(ts := 12.0), 20.0)

if __name__ == '__main__': unittest.main()
